/**
 * DESIGN GENERATORS — METHODS (2026-11-09) — browser suite. Studio on :3000 with AI_API_URL=fake: (the sandbox).
 *
 *   1  the method library: every method listed, names and group headings readable (contrast ≥ 4.5:1)
 *   2  every design-file method opens with a worked sample generated by the real generator (tasks + quality figures)
 *   3  Sample → guided set-up → Generate: the design is attached, previewed, with a live recommendation; JSON export
 *   4  Describe it: the spec's example sentence → understood, recommended with reasons, missing names asked;
 *      answered → generated; by voice too
 *   5  a custom experimental design (Williams) from a sentence: carry-over balanced
 *   6  a study methodology: its sample built by the real builder → Study design with the method chosen; the Study
 *      design list is readable
 *   7  Intelligent Mode: an incomplete design request is explained and Design Generators starts on it; no page errors
 */
import assert from "node:assert/strict";
import { chromium } from "./lib/playwright.mjs";
import { openTab, switchMode } from "./lib/nav.mjs";

const STUDIO = process.env.STUDIO_URL ?? "http://localhost:3000";
let passed = 0;
const ok = (m) => { passed++; console.log(`  ok   ${m}`); };
const browser = await chromium.launch({ args: ["--use-fake-device-for-media-stream", "--use-fake-ui-for-media-stream"] });
const errors = [];
const p = await (await browser.newContext({ viewport: { width: 1500, height: 1000 }, acceptDownloads: true, permissions: ["microphone"] })).newPage();
p.on("pageerror", (e) => errors.push(String(e)));
for (let i = 0; i < 20; i++) { try { const r = await fetch(`${STUDIO}/sandbox?mode=studio`); if (r.status < 500) break; } catch { /* starting */ } await new Promise((r) => setTimeout(r, 2000)); }
await p.goto(`${STUDIO}/sandbox?mode=studio`, { waitUntil: "load" });
await p.waitForSelector(".block-badge", { timeout: 60000 });
await switchMode(p, "studio").catch(() => {});

/* WCAG contrast of an element's text against its (first opaque) background */
const contrast = (sel) => p.$eval(sel, (el) => {
  const rgb = (c) => (c.match(/[\d.]+/g) ?? []).map(Number);
  const lum = ([r, g, b]) => { const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }; return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b); };
  let bg = null, n = el;
  while (n) { const c = getComputedStyle(n).backgroundColor; const v = rgb(c); if (v.length >= 3 && (v.length < 4 || v[3] > 0.9)) { bg = v; break; } n = n.parentElement; }
  bg ??= [255, 255, 255];
  const fg = rgb(getComputedStyle(el).color);
  const [a, b] = [lum(fg), lum(bg)].sort((x, y) => y - x);
  return (a + 0.05) / (b + 0.05);
});
const attachedCount = () => p.$$eval('h3.sec:has-text("Attached design files") ~ .card', (c) => c.length);

console.log("\n1 — the method library");
await openTab(p, "Design Generators");
await p.waitForSelector('[data-testid="design-workspace"] [data-testid="method-library"]');
const names = await p.$$eval('[data-testid="method-library"] .ml-name', (n) => n.map((x) => x.textContent));
assert.equal(names.length, 7 + 31, `${names.length} methods (7 design-file methods + every study methodology)`);
for (const want of ["Choice-based conjoint (CBC)", "MaxDiff (best–worst scaling)", "Adaptive CBC (ACBC)", "Menu-based conjoint (MBC)", "Rating-based conjoint (CVA)", "Custom experimental design", "Van Westendorp Price Sensitivity Meter"]) assert.ok(names.includes(want), want);
const groups = await p.$$eval('[data-testid="method-library"] .ml-group-h', (h) => h.map((x) => x.childNodes[0].textContent));
assert.ok(groups.includes("Pricing & price sensitivity") && groups.includes("Product & concept testing") && groups.includes("Brand research"), groups.join("|"));
const cName = await contrast('[data-testid="method-library"] .ml-name'), cDesc = await contrast('[data-testid="method-library"] .ml-desc'), cHead = await contrast('[data-testid="method-library"] .ml-group-h');
assert.ok(cName >= 7 && cDesc >= 4.5 && cHead >= 4.5, `name ${cName.toFixed(1)} desc ${cDesc.toFixed(1)} heading ${cHead.toFixed(1)}`);
ok(`${names.length} methods in ${groups.length} groups; contrast — names ${cName.toFixed(1)}:1, descriptions ${cDesc.toFixed(1)}:1, headings ${cHead.toFixed(1)}:1`);

console.log("\n2 — a worked sample for every design method");
for (const k of ["conjoint", "maxdiff", "acbc", "menu", "cva", "experiment", "custom"]) {
  await p.click(`[data-testid="method-design:${k}"]`);
  await p.waitForSelector(`[data-testid="design-method-${k}"] [data-testid="dm-sample"] [data-testid="design-preview"]`, { timeout: 15000 });
  const tasks = await p.$$eval(`[data-testid="design-method-${k}"] [data-testid="design-task"]`, (t) => t.length);
  if (["conjoint", "maxdiff", "menu", "cva"].includes(k)) assert.ok(tasks >= 2, `${k}: ${tasks} tasks shown`);
}
await p.click('[data-testid="method-design:conjoint"]');
const facts = await p.textContent('[data-testid="design-method-conjoint"] [data-testid="design-facts"]');
assert.match(facts, /D-efficiency/); assert.match(facts, /Alternatives per task3/);
ok("CBC, MaxDiff, ACBC, MBC, CVA, experimental and column designs each open with a generated sample (tasks, parameters, quality)");

console.log("\n3 — sample → guided set-up → generate");
const before = await attachedCount();
await p.click('[data-testid="dm-use-sample"]');
await p.waitForSelector('[data-testid="dm-guided"] [data-testid="dg-recommendation"]');
assert.match(await p.textContent('[data-testid="dg-recommendation"]'), /alternatives per task/i);
await p.click('[data-testid="dm-guided"] [data-testid="dg-generate"]');
await p.waitForFunction((n) => document.querySelectorAll('h3.sec ~ .card').length > n, before, { timeout: 20000 }).catch(() => {});
assert.equal(await attachedCount(), before + 1);
assert.ok(await p.$('[data-testid="dm-guided"] [data-testid="design-preview"]'));
const [dl] = await Promise.all([p.waitForEvent("download"), p.click('[data-testid="dm-guided"] button:has-text("⬇ JSON")')]);
const json = JSON.parse(await (await import("node:fs")).promises.readFile(await dl.path(), "utf8"));
assert.equal(json.kind, "conjoint"); assert.ok(json.rows.length > 0 && json.config.attributes.length === 5 && typeof json.seed === "number");
ok(`the streaming sample generated and attached (${json.rows.length} rows); recommendation shown; JSON export carries config, seed and rows`);

console.log("\n4 — Describe it (words and voice)");
await p.click('[data-testid="dm-tab-describe"]');
await p.fill('[data-testid="dm-describe-text"]', "I want to create a choice-based conjoint study with six attributes and three to four levels per attribute. I need an efficient, balanced experimental design with 12 choice tasks per respondent and three alternatives per task. Please recommend the optimal design.");
await p.click('[data-testid="dm-understand"]');
await p.waitForSelector('[data-testid="dm-recommendation"]');
const recText = await p.textContent('[data-testid="dm-recommendation"]');
assert.match(recText, /6 attributes, 3–4 levels each/); assert.match(recText, /12 tasks per respondent/); assert.match(recText, /Orme/);
assert.ok(await p.$('[data-testid="dm-answer-attributes"]'), "asks for the attribute names");
await p.fill('[data-testid="dm-answer-attributes"]', "Brand: Acme, Globex, Initech\nPrice: $9, $14, $19, $24\nStorage: 64 GB, 128 GB, 256 GB\nBattery: 1 day, 2 days, 3 days\nCamera: Standard, Pro, Pro Max, Ultra\nWarranty: 1 year, 2 years, 3 years");
await p.waitForFunction(() => !document.querySelector('[data-testid="dm-questions"]')?.textContent?.includes("placeholders") || true);
await p.click('[data-testid="dm-use-recommendation"]');
await p.waitForSelector('[data-testid="dm-guided"] [data-testid="dg-generate"]');
const before2 = await attachedCount();
await p.click('[data-testid="dm-guided"] [data-testid="dg-generate"]');
await p.waitForFunction((n) => document.querySelectorAll('h3.sec ~ .card').length > n, before2, { timeout: 20000 }).catch(() => {});
assert.equal(await attachedCount(), before2 + 1);
const tasksShown = await p.$$eval('[data-testid="dm-guided"] [data-testid="design-task"] th', (t) => t.map((x) => x.textContent));
assert.ok(tasksShown.includes("Camera") && tasksShown.includes("Warranty"), "the named attributes are in the generated tasks");
ok("the spec's sentence → 6 attributes, 3–4 levels, 12 tasks, 3 alternatives, Orme's sample rule; names asked, given, generated");
await p.click('[data-testid="dm-tab-describe"]');
await p.fill('[data-testid="dm-describe-text"]', "");
await p.evaluate(() => window.__rescriptVoiceHint("a MaxDiff of 15 product claims, 5 per task", "en"));
await p.click('[data-testid="dm-describe"] [data-testid="agw-mic"]');
await p.waitForFunction(() => document.querySelector('[data-testid="dm-describe"] [data-testid="agw-voice"]')?.dataset.state === "recording");
await p.waitForTimeout(700);
await p.click('[data-testid="dm-describe"] [data-testid="agw-voice-stop"]');
await p.waitForFunction(() => document.querySelector('[data-testid="dm-describe-text"]')?.value?.includes("MaxDiff"), null, { timeout: 20000 });
await p.click('[data-testid="dm-understand"]');
await p.waitForSelector('[data-testid="dm-recommendation"][data-kind="maxdiff"]');
ok("by voice: “a MaxDiff of 15 product claims, 5 per task” → in the box, editable → recommended as MaxDiff");

console.log("\n5 — a custom experimental design from a sentence");
await p.click('[data-testid="method-design:experiment"]');
await p.click('[data-testid="dm-tab-describe"]');
await p.fill('[data-testid="dm-describe-text"]', "Show 4 ads in sequence and balance order and carry-over effects.\ntreatments: Ad A, Ad B, Ad C, Ad D");
await p.click('[data-testid="dm-understand"]');
await p.waitForSelector('[data-testid="dm-recommendation"][data-kind="experiment"]');
assert.match(await p.textContent('[data-testid="dm-why"]'), /Williams design/);
await p.click('[data-testid="dm-use-recommendation"]');
await p.click('[data-testid="dm-guided"] [data-testid="dg-generate"]');
await p.waitForSelector('[data-testid="dm-guided"] [data-testid="design-facts"]');
assert.match(await p.textContent('[data-testid="dm-guided"] [data-testid="design-facts"]'), /Carry-overbalanced/);
ok("“4 ads in sequence, balance carry-over” → Williams design → generated, carry-over balanced");

console.log("\n6 — a study methodology → Study design");
await p.click('[data-testid="method-study:van_westendorp"]');
await p.waitForSelector('[data-testid="study-method-van_westendorp"] [data-testid="dm-study-sample"] .dm-qs li');
assert.ok((await p.$$eval('[data-testid="dm-study-sample"] .dm-qs li', (l) => l.length)) >= 4);
await p.click('[data-testid="dm-open-study"]');
await p.waitForSelector('[data-testid="study-design"] [data-testid="sd-chosen"]');
assert.match(await p.textContent('[data-testid="sd-chosen"]'), /Van Westendorp Price Sensitivity Meter/);
const sdName = await contrast('[data-testid="sd-method"] .ml-name'), sdHead = await contrast('[data-testid="sd-method"] .ml-group-h');
assert.ok(sdName >= 7 && sdHead >= 4.5);
ok(`Van Westendorp: sample questions built → Study design opens with it chosen; its list reads at ${sdName.toFixed(1)}:1 / ${sdHead.toFixed(1)}:1`);

console.log("\n7 — Intelligent Mode");
await switchMode(p, "intelligent");
await openTab(p, "Questions").catch(() => {});
await p.waitForSelector('[data-testid="intelligent-view"]');
await p.fill('[data-testid="iq-input"]', "Create a choice-based conjoint with five attributes, 10 tasks and 3 alternatives per task");
await p.click('[data-testid="iq-send"]');
await p.waitForFunction(() => /nothing has been generated yet/.test(document.querySelector('[data-testid="iq-log"]')?.textContent ?? ""), null, { timeout: 20000 });
const said = await p.textContent('[data-testid="iq-log"]');
assert.match(said, /To generate it I still need: Name the 5 attributes/);
await switchMode(p, "studio");
await openTab(p, "Design Generators");
await p.waitForSelector('[data-testid="design-method-conjoint"] [data-testid="dm-describe"]');
assert.match(await p.inputValue('[data-testid="dm-describe-text"]'), /five attributes, 10 tasks/);
ok("Intelligent Mode explains, asks for the attribute names, and Design Generators starts on the request");

assert.deepEqual(errors, []);
ok("no page errors");
await browser.close();
console.log(`\n${passed} passed`);
